// Offline support. The app shell is cached on install; a game's files when
// it's opened (so someone sent a link to one game downloads just that one);
// everything once you're browsing the arcade (or have installed it). Then
// everything cached is served from the cache. sw-manifest.js (generated by
// tools/build-sw.mjs) lists every file plus a content hash, so any change to
// the app produces a new cache version.
importScripts('sw-manifest.js');

const { version, files } = self.PRECACHE;
const CACHE = `pocket-arcade-${version}`;
const gameOf = (f) => (f.startsWith('games/') ? f.split('/')[1] : null);
// The shell: everything but the games -- except their little card pictures,
// for the home screen.
const CORE = files.filter((f) => !gameOf(f) || /^games\/[^/]+\/art\.js$/.test(f));
const filesOf = (games) => files.filter((f) => !CORE.includes(f) && (games === 'all' || games.includes(gameOf(f))));
// A request's path relative to the app (as the manifest lists it).
const rel = (url) => {
  const p = new URL(url).pathname.slice(new URL(self.registration.scope).pathname.length);
  return p === '' ? './' : p;
};

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    // The shell, and whichever games the last version had cached. (Say
    // which version's coming first: looking through the old cache takes a
    // moment.)
    await report(0, CORE.length);
    await precache([...CORE, ...filesOf(await cachedGames())]);
    // A first install takes over straight away. An update waits until the
    // player taps Update on the home screen -- never in the middle of a game.
    if (!self.registration.active) self.skipWaiting();
  })());
});

// The games cached by earlier versions (any of their files, not just the
// card picture).
async function cachedGames() {
  const games = new Set();
  for (const key of await caches.keys()) {
    if (!key.startsWith('pocket-arcade-') || key === CACHE) continue;
    for (const req of await (await caches.open(key)).keys()) {
      const f = rel(req.url);
      if (gameOf(f) && !CORE.includes(f)) games.add(gameOf(f));
    }
  }
  return [...games];
}

// Download files into the new cache a few at a time, telling open pages how
// far along it is so they can show a progress bar for updates.
async function report(done, total) {
  const pages = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  for (const page of pages) page.postMessage({ type: 'UPDATE_PROGRESS', version: self.PRECACHE.appVersion, done, total });
}

async function precache(list) {
  const cache = await caches.open(CACHE);
  const total = list.length;
  let done = 0;
  await report(done, total);
  const queue = list.slice();
  const fetchNext = async () => {
    while (queue.length) {
      const file = queue.shift();
      const res = await fetch(new Request(file, { cache: 'reload' }));
      if (!res.ok) throw new Error(`precache ${file}: ${res.status}`);
      await cache.put(file, res);
      done++;
      await report(done, total);
    }
  };
  await Promise.all(Array.from({ length: 6 }, fetchNext));
}

// More of the app for offline (a game opened, or the whole arcade), into the
// current cache -- just what isn't there already.
async function cacheMore(games) {
  const cache = await caches.open(CACHE);
  const missing = [];
  for (const f of filesOf(games)) if (!(await cache.match(f))) missing.push(f);
  await Promise.all(missing.map(async (f) => {
    const res = await fetch(new Request(f, { cache: 'reload' }));
    if (res.ok) await cache.put(f, res);
  }));
}

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('pocket-arcade-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('message', (event) => {
  const type = event.data && event.data.type;
  if (type === 'SKIP_WAITING') self.skipWaiting();
  // Lets the page tell the player which version is waiting to install.
  if (type === 'GET_VERSION') event.ports[0]?.postMessage(self.PRECACHE.appVersion);
  // A game opened, or the arcade browsed: cache it for offline.
  if (type === 'CACHE') event.waitUntil(cacheMore(event.data.games).catch(() => {}));
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  event.respondWith(
    caches.open(CACHE).then(async (cache) => {
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      if (req.mode === 'navigate') {
        const shell = await cache.match('./');
        if (shell) return shell;
      }
      // Not cached yet (a game not opened before): from the network, and
      // kept for next time.
      const res = await fetch(req);
      const f = rel(req.url);
      if (res.ok && files.includes(f)) cache.put(f, res.clone()).catch(() => {});
      return res;
    }),
  );
});
